const config = $('Set Audit Ledger Config').first().json;
const stored = $input.all().filter(i => i.json && i.json.last_entry_id);
return [{ json: {
  guildId: String(config.guildId || ''),
  afterId: stored.length ? String(stored[0].json.last_entry_id) : '0',
  pageSize: Number(config.pageSize || 100),
  maxPagesPerRun: Number(config.maxPagesPerRun || 5),
  digestWeekday: Number(config.digestWeekday || 1),
  digestLookbackDays: Number(config.digestLookbackDays || 7),
  runStartedAt: new Date().toISOString(),
  isFirstRun: stored.length === 0
} }];

const actionNames = {
  1: 'guild update', 10: 'channel create', 11: 'channel update', 12: 'channel delete',
  13: 'overwrite create', 14: 'overwrite update', 15: 'overwrite delete',
  20: 'member kick', 21: 'member prune', 22: 'member ban add', 23: 'member ban remove',
  24: 'member update', 25: 'member role update', 26: 'member move', 27: 'member disconnect',
  28: 'bot add', 30: 'role create', 31: 'role update', 32: 'role delete',
  40: 'invite create', 42: 'invite delete', 50: 'webhook create', 51: 'webhook update',
  52: 'webhook delete', 60: 'emoji create', 61: 'emoji update', 62: 'emoji delete',
  72: 'message delete', 73: 'message bulk delete', 74: 'message pin', 75: 'message unpin',
  80: 'integration create', 82: 'integration delete', 83: 'stage create', 85: 'stage delete',
  90: 'sticker create', 92: 'sticker delete', 100: 'event create', 102: 'event delete',
  110: 'thread create', 111: 'thread update', 112: 'thread delete',
  121: 'command permission update', 140: 'automod rule create',
  143: 'automod block message', 145: 'automod timeout'
};
const channelActions = [10, 11, 12, 13, 14, 15, 110, 111, 112];
const messageActions = [72, 73, 74, 75];
const roleActions = [30, 31, 32];
const cursor = $('Build Fetch Cursor').first().json;
const users = {};
const entries = [];
for (const item of $input.all()) {
  const page = item.json || {};
  for (const u of (page.users || [])) { users[u.id] = u.global_name || u.username || u.id; }
  for (const e of (page.audit_log_entries || [])) { entries.push(e); }
}
entries.sort((a, b) => a.id.length - b.id.length || (a.id < b.id ? -1 : a.id > b.id ? 1 : 0));
const rows = entries.map(e => {
  const type = Number(e.action_type);
  const changes = e.changes || [];
  let action = actionNames[type] || ('action ' + type);
  if (type === 24) {
    const timeout = changes.filter(c => c.key === 'communication_disabled_until')[0];
    if (timeout && timeout.new_value) { action = 'member timeout add'; }
    else if (timeout) { action = 'member timeout remove'; }
  }
  let targetKind = 'user';
  if (channelActions.indexOf(type) !== -1) { targetKind = 'channel'; }
  else if (messageActions.indexOf(type) !== -1) { targetKind = 'message'; }
  else if (roleActions.indexOf(type) !== -1) { targetKind = 'role'; }
  const targetId = e.target_id ? String(e.target_id) : '';
  const targetName = targetKind === 'user' ? (users[targetId] || targetId) : targetId;
  const createdAt = new Date(Number(BigInt(e.id) >> BigInt(22)) + 1420070400000).toISOString();
  return { json: {
    entry_id: String(e.id),
    created_at: createdAt,
    guild_id: cursor.guildId,
    action: action,
    action_type: type,
    moderator_id: e.user_id ? String(e.user_id) : '',
    moderator_name: users[e.user_id] || (e.user_id ? String(e.user_id) : 'unknown'),
    target_kind: targetKind,
    target_id: targetId,
    target_name: targetName,
    reason: e.reason || '',
    changed_keys: changes.map(c => c.key).join(', '),
    archived_at: cursor.runStartedAt,
    run_max_entry_id: ''
  } };
});
if (rows.length === 0) { return []; }
const maxId = rows[rows.length - 1].json.entry_id;
for (const r of rows) { r.json.run_max_entry_id = maxId; }
return rows;

const br = '\n';
const cursor = $('Build Fetch Cursor').first().json;
const days = Number(cursor.digestLookbackDays || 7);
const cutoff = Date.now() - days * 24 * 60 * 60 * 1000;
const rows = $input.all().map(i => i.json)
  .filter(r => r && r.created_at && Date.parse(r.created_at) >= cutoff);
const byModerator = {};
const byAction = {};
for (const r of rows) {
  const mod = r.moderator_name || r.moderator_id || 'unknown';
  byModerator[mod] = (byModerator[mod] || 0) + 1;
  const act = r.action || 'unknown';
  byAction[act] = (byAction[act] || 0) + 1;
}
const rank = o => Object.keys(o).map(k => [k, o[k]]).sort((a, b) => b[1] - a[1]).slice(0, 10);
const render = o => rank(o).map(p => '- ' + p[0] + ': ' + p[1]).join(br) || '- nothing logged';
const header = '*Discord audit log digest, last ' + days + ' days*';
const total = rows.length + ' entries from ' + Object.keys(byModerator).length + ' moderators.';
const body = [header, total, '', '*By moderator*', render(byModerator), '', '*By action*',
  render(byAction)].join(br);
return [{ json: {
  windowDays: days,
  totalEntries: rows.length,
  moderatorCount: Object.keys(byModerator).length,
  digestText: body.slice(0, 2800)
} }];
